20	// 正运动学计算 (从关节角度计算末端位置)
21	static esp_err_t forward_kinematics(robotic_arm_handle_t *handle, robotic_arm_position_t *position) {
22	    if (!handle || !position) {
23	        return ESP_ERR_INVALID_ARG;
24	    }
25	    
26	    // 获取当前关节角度并转换为弧度
27	    float base_rad = deg_to_rad(handle->current_angles.base);
28	    float shoulder_rad = deg_to_rad(handle->current_angles.shoulder);
29	    float elbow_rad = deg_to_rad(handle->current_angles.elbow);
30	    float wrist_rad = deg_to_rad(handle->current_angles.wrist);
31	    
32	    // 获取机械臂参数
33	    float arm_length = handle->kinematics.arm_length;
34	    float forearm_length = handle->kinematics.forearm_length;
35	    float wrist_length = handle->kinematics.wrist_length;
36	    float base_height = handle->kinematics.base_height;
37	    
38	    // 计算位置
39	    float r_shoulder = arm_length * sin(shoulder_rad);
40	    float z_shoulder = arm_length * cos(shoulder_rad);
41	    
42	    float r_elbow = forearm_length * sin(shoulder_rad + elbow_rad);
43	    float z_elbow = forearm_length * cos(shoulder_rad + elbow_rad);
44	    
45	    float r_wrist = wrist_length * sin(shoulder_rad + elbow_rad + wrist_rad);
46	    float z_wrist = wrist_length * cos(shoulder_rad + elbow_rad + wrist_rad);
47	    
48	    float r = r_shoulder + r_elbow + r_wrist;
49	    float z = base_height + z_shoulder + z_elbow + z_wrist;
50	    
51	    // 设置位置
52	    position->x = r * cos(base_rad);
53	    position->y = r * sin(base_rad);
54	    position->z = z;
55	    
56	    // 计算末端姿态
57	    position->roll = 0; // 简化模型，假设没有滚转
58	    position->pitch = rad_to_deg(shoulder_rad + elbow_rad + wrist_rad);
59	    position->yaw = handle->current_angles.base;
60	    position->gripper_angle = handle->current_angles.gripper;
61	    
62	    return ESP_OK;
63	}
