62	    }
63	    
64	    // 获取文件大小
65	    fseek(f, 0, SEEK_END);
66	    long fsize = ftell(f);
67	    fseek(f, 0, SEEK_SET);
68	    
69	    // 分配内存并读取文件
70	    char *buffer = malloc(fsize + 1);
71	    if (buffer == NULL) {
72	        ESP_LOGE(TAG, "内存分配失败");
73	        fclose(f);
74	        httpd_resp_send_500(req);
75	        return ESP_FAIL;
76	    }
77	    
78	    size_t read_size = fread(buffer, 1, fsize, f);
79	    fclose(f);
80	    
81	    if (read_size != fsize) {
82	        ESP_LOGE(TAG, "读取文件失败");
83	        free(buffer);
84	        httpd_resp_send_500(req);
85	        return ESP_FAIL;
86	    }
87	    
88	    buffer[fsize] = '\0';
89	    
90	    // 发送HTML内容
91	    httpd_resp_set_type(req, "text/html");
92	    httpd_resp_send(req, buffer, fsize);
93	    
94	    free(buffer);
95	    return ESP_OK;
96	}
