    def _v2_engage(self):
        """首次收到 v2 指令时接管运动：以当前位置为起点，清空残留状态。"""
        if not self.v2_active:
            self.v2_active = True
            self.queue.clear()
            self.target = dict(self.pwm)

    def v2_move(self, angles, speed=None, replace=True):
        bad = []
        for j, v in angles.items():
            lo, hi = SERVO_SPECS[j]["min_angle"], SERVO_SPECS[j]["max_angle"]
            if not (lo <= v <= hi):
                bad.append({"joint": j, "value": v, "min": lo, "max": hi})
        if bad:
            return False, bad
        with self.lock:
            self._v2_engage()
            if replace:
                self.queue.clear()
                self.target.update({j: float(v) for j, v in angles.items()})
            else:
                self.queue.append({"t_ms": 0, "angles": {j: float(v) for j, v in angles.items()}})
            if speed is not None:
                self.speed = max(V2_MIN_SPEED, min(V2_MAX_SPEED, float(speed)))
            self.seq += 1
            seq = self.seq
            eta = int(1000 * max(abs(self.target[j] - self.pwm[j]) for j in JOINTS) / self.speed)
        return True, dict(seq=seq, eta_ms=eta)

    def v2_trajectory(self, points, speed=None):
        norm = []
        for pt in points:
            t = float(pt.get("t_ms", 0))
            ang = {j: float(pt[j]) for j in JOINTS if j in pt and pt[j] is not None}
            for j, v in ang.items():
                lo, hi = SERVO_SPECS[j]["min_angle"], SERVO_SPECS[j]["max_angle"]
                if not (lo <= v <= hi):
                    return False, [{"joint": j, "value": v, "min": lo, "max": hi}]
            norm.append({"t_ms": int(t), "angles": ang})
        norm.sort(key=lambda p: p["t_ms"])
        with self.lock:
            if speed is not None:
                self.speed = max(V2_MIN_SPEED, min(V2_MAX_SPEED, float(speed)))
            self.queue = norm
            self.seq += 1
            if norm:
                self.target.update(norm[0]["angles"])
        return True, dict(seq=self.seq, points=len(norm))

