{"content": """"拉取 ESP-IDF 子模块：解析 .gitmodules（含相对 URL）+ 按 pin 的 commit 取 tarball。

Windows 下 tar 无法创建符号链接，故手工跳过 symlink 成员。
"""

import io
import os
import re
import shutil
import tarfile
import time
import urllib.request

IDF = r"C:\esp32-tools\esp-idf"
SHAFILE = r"C:\esp32-tools\submodules.tsv"
TMP = r"C:\esp32-tools\sub.tar.gz"

NEEDED = [
    "components/mbedtls/mbedtls", "components/lwip/lwip", "components/json/cJSON",
    "components/esp_phy/lib", "components/esp_wifi/lib", "components/spiffs/spiffs",
    "components/heap/tlsf", "components/esp_coex/lib", "components/bt/controller/lib_esp32",
    "components/esptool_py/esptool", "components/mqtt/esp-mqtt", "components/unity/unity",
    "components/cmock/CMock", "components/protobuf-c/protobuf-c",
    "components/openthread/openthread", "components/wpa_supplicant/esp_supplicant",
]


def parse_gitmodules():
    out = {}
    txt = open(os.path.join(IDF, ".gitmodules"), encoding="utf-8").read()
    for block in txt.split("[submodule")[1:]:
        p = re.search(r'path\s*=\s*(\S+)', block)
        u = re.search(r'url\s*=\s*(\S+)', block)
        if p and u:
            out[p.group(1)] = u.group(1)
    return out


def parse_shas():
    out = {}
    if not os.path.exists(SHAFILE):
        return out
    for line in open(SHAFILE, encoding="utf-8"):
        parts = line.rstrip("\n").split("\t")
        if len(parts) == 3 and not line.startswith("#"):
            out[parts[0]] = parts[2]
    return out


def to_repo(url):
    u = url.strip()
    u = re.sub(r"^https?://github\.com/", "", u)
    u = re.sub(r"^(\.\./)+", "", u)
    u = re.sub(r"\.git$", "", u)
    return u


def fetch(repo, sha, dest):
    url = "https://codeload.github.com/%s/tar.gz/%s" % (repo, sha)
    for attempt in range(3):
        try:
            with urllib.request.urlopen(url, timeout=180) as r:
                data = r.read()
            break
        except Exception as e:
            print("   重试 %d: %s" % (attempt + 1, e))
            time.sleep(2)
    else:
        return False, "下载失败"
    if len(data) < 800:
        return False, "内容异常(%d B)" % len(data)
    with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as tf:
        members = [m for m in tf.getmembers() if not (m.issym() or m.islnk())]
        if os.path.exists(dest):
            shutil.rmtree(dest, ignore_errors=True)
        os.makedirs(dest, exist_ok=True)
        for m in members:
            m.name = "/".join(m.name.split("/")[1:])       # 去掉顶层目录
            if not m.name:
                continue
            if m.isdir():
                os.makedirs(os.path.join(dest, m.name), exist_ok=True)
            elif m.isfile():
                p = os.path.join(dest, m.name)
                os.makedirs(os.path.dirname(p), exist_ok=True)
                with open(p, "wb") as f:
                    f.write(tf.extractfile(m).read())
    return True, "%d 项" % len(os.listdir(dest))


def main():
    gm, shas = parse_gitmodules(), parse_shas()
    print("gitmodules 条目 %d，已解析 SHA %d" % (len(gm), len(shas)))
    todo = [p for p in NEEDED if p in gm] + [p for p in gm if p not in NEEDED]
    for path in todo:
        dest = os.path.join(IDF, path)
        if os.path.isdir(dest) and os.listdir(dest):
            print("已存在 %s" % path)
            continue
        sha = shas.get(path)
        if not sha:
            print("无 SHA，跳过 %s" % path)
            continue
        repo = to_repo(gm[path])
        print("-- %s <- %s@%s" % (path, repo, sha[:8]))
        ok, msg = fetch(repo, sha, dest)
        print("   %s %s" % ("ok" if ok else "失败", msg))
    print("== 关键子模块 ==")
    for p in NEEDED[:8]:
        d = os.path.join(IDF, p)
        print("%-42s %s" % (p, len(os.listdir(d)) if os.path.isdir(d) else "缺失"))


if __name__ == "__main__":
    main()
