{"content": "/*
 * arm_api —— 面向 AI/上位机的机械臂控制接口
 *
 * 设计要点（与上位机数字孪生逐项对应）：
 *   1. 唯一运动任务：所有关节指令先进队列，由 50 Hz 运动任务统一插值输出，
 *      彻底消除"每个关节一条任务 + 无仲裁"导致的指令打架问题；
 *   2. 重定向语义：/api/move 立即改写目标（适合视觉伺服的连续小步修正），
 *      /api/trajectory 提交整条轨迹（适合预规划动作），二者互不阻塞；
 *   3. 关节角 -> 舵机角 的标定表：joint = s * servo + o，存 NVS，可在线标定；
 *   4. 笛卡尔接口：/api/pose 正解、/api/move_xyz 逆解（超出工作空间或行程时
 *      明确报错，而不是静默截断）；
 *   5. 安全：急停 /api/estop、停止 /api/stop（保持位置）、指令保活超时、
 *      学习模式（手动/录制/回放）期间拒绝 AI 指令。
 */

#pragma once

#include <stdbool.h>
#include <stdint.h>

#include "esp_err.h"
#include "freertos/FreeRTOS.h"
#include "freertos/queue.h"
#include "esp_http_server.h"
#include "robotic_arm.h"

#ifdef __cplusplus
extern "C" {
#endif

#define ARM_API_MAX_SERVOS         ROBOTIC_ARM_MAX_SERVOS
#define ARM_API_MAX_WAYPOINTS      8        /* 单次 /api/trajectory 的路径点数 */
#define ARM_API_BODY_MAX           1024     /* JSON 请求体上限（原 /api/control 只有 99 字节） */
#define ARM_API_TICK_HZ            50
#define ARM_API_DEFAULT_SPEED      60.0f    /* deg/s */
#define ARM_API_MIN_SPEED          5.0f
#define ARM_API_MAX_SPEED          180.0f
#define ARM_API_WATCHDOG_MS        3000     /* 超过该时间无指令则按当前目标保持 */
#define ARM_API_MOVE_TIMEOUT_MS    15000    /* 单条指令最长执行时间，超时停机 */

typedef struct {
    robotic_arm_handle_t *arm;      /*!< 机械臂句柄 */
    float speed_default;            /*!< 默认速度 deg/s */
} arm_api_config_t;

/* 关节角与舵机角的标定关系：joint = sign * servo + offset */
typedef struct {
    int8_t  sign[ARM_API_MAX_SERVOS];
    float   offset[ARM_API_MAX_SERVOS];
} arm_api_calib_t;

/* 统一状态快照（供 HTTP 与内部逻辑使用） */
typedef struct {
    float   angle[ARM_API_MAX_SERVOS];    /*!< 当前舵机角（插值后的实际指令值） */
    float   target[ARM_API_MAX_SERVOS];   /*!< 目标舵机角 */
    bool    moving;                       /*!< 是否仍在运动 */
    bool    estop;                        /*!< 急停锁存 */
    bool    external_busy;                /*!< 学习模式等占用中 */
    uint32_t seq;                         /*!< 指令序号 */
    uint8_t queued;                       /*!< 队列中剩余路径点数 */
    float   speed;                        /*!< 当前速度设定 */
    uint32_t uptime_ms;
} arm_api_state_t;

/**
 * @brief 初始化并启动唯一运动任务
 */
esp_err_t arm_api_init(const arm_api_config_t *config);

/**
 * @brief 在已有 HTTP 服务器上注册 arm_api 的 URI
 *
 * 注册：GET /api/state /api/pose /api/limits /api/calib，POST /api/move
 *      /api/move_xyz /api/trajectory /api/stop /api/estop /api/home /api/calib
 */
esp_err_t arm_api_register(httpd_handle_t server);

/**
 * @brief 关节指令入口（web_controller 的 /api/control 也走这里）
 *
 * @param angles  目标角度，未包含的关节保持当前目标
 * @param speed   速度 deg/s，<=0 表示使用默认值
 * @param seq_out 返回指令序号
 */
esp_err_t arm_api_move_joints(const robotic_arm_angles_t *angles, float speed,
                              uint32_t *seq_out);

/**
 * @brief 停止：清空队列并保持当前位置（不卸载力矩）
 */
esp_err_t arm_api_stop(void);

/**
 * @brief 急停：停止 + 释放舵机力矩，需 /api/home 或 /api/estop 清除后才能再动
 */
esp_err_t arm_api_estop(void);

/**
 * @brief 读取状态快照
 */
esp_err_t arm_api_get_state(arm_api_state_t *out);

/**
 * @brief 生成与 /api/state 相同格式的 JSON（供 web_controller 复用）
 */
esp_err_t arm_api_state_json(char *buf, size_t len);

/**
 * @brief 标记"有外部模块正在直接写舵机"（学习模式/回放），期间运动任务让出控制权
 *
 * 这样既保留了原有的手动学习功能，又不会与 AI 指令互相打架。
 */
void arm_api_notify_external_write(bool busy);

/**
 * @brief 当前标定表副本
 */
const arm_api_calib_t *arm_api_get_calib(void);

#ifdef __cplusplus
}
#endif
