/* 正解：舵机角 -> 末端位置（与 robotic_arm.c 的 FK 约定一致） */
static void arm_api_fk(const float servo_angle[ARM_API_MAX_SERVOS],
                       const robotic_arm_kinematics_t *kin, float *x, float *y, float *z)
{
    float b = deg2rad(joint_of_servo(0, servo_angle[0]));
    float s = deg2rad(joint_of_servo(1, servo_angle[1]));
    float e = deg2rad(joint_of_servo(2, servo_angle[2]));
    float w = deg2rad(joint_of_servo(3, servo_angle[3]));
    float r = kin->arm_length * sinf(s)
            + kin->forearm_length * sinf(s + e)
            + kin->wrist_length * sinf(s + e + w);
    float zz = kin->base_height
             + kin->arm_length * cosf(s)
             + kin->forearm_length * cosf(s + e)
             + kin->wrist_length * cosf(s + e + w);
    *x = r * cosf(b);
    *y = r * sinf(b);
    *z = zz;
}

/*
 * 逆解：笛卡尔位置 -> 舵机角。
 * FK 约定：平面内 u(t) = (sin t, cos t)，t 自 +z 轴量起、转向 +r；
 * 腕心 W = 末端 - L3*(sin wp, cos wp)。原 robotic_arm.c 的逆解把 sin/cos 用反了，
 * 与自家正解不自洽（上位机实测往返误差中位数 282 mm），此处按自洽形式重写。
 *
 * 返回 ESP_OK / ESP_ERR_INVALID_ARG（几何不可达）/ ESP_ERR_INVALID_STATE（超出舵机行程）
 */
static esp_err_t arm_api_ik(float x, float y, float z, float pitch_deg, bool elbow_up,
                            const robotic_arm_kinematics_t *kin,
                            float servo_out[ARM_API_MAX_SERVOS],
                            float *joint_out)
{
    const float L1 = kin->arm_length, L2 = kin->forearm_length, L3 = kin->wrist_length;
    float r = sqrtf(x * x + y * y);
    float zz = z - kin->base_height;
    float wp = deg2rad(pitch_deg);

    float wx = r - L3 * sinf(wp);
    float wz = zz - L3 * cosf(wp);
    float sw = sqrtf(wx * wx + wz * wz);
    if (sw > L1 + L2 - 1e-3f || sw < fabsf(L1 - L2) + 1e-3f) {
        ESP_LOGW(TAG, "IK: 腕心不可达 |W| = %.2f mm", sw);
        return ESP_ERR_INVALID_ARG;
    }

    float alpha = atan2f(wx, wz);
    float c_elbow = clampf((sw * sw - L1 * L1 - L2 * L2) / (2.0f * L1 * L2), -1.0f, 1.0f);
    float elbow = elbow_up ? -acosf(c_elbow) : acosf(c_elbow);
    float shoulder = alpha - atan2f(L2 * sinf(elbow), L1 + L2 * cosf(elbow));
    float wrist = wp - shoulder - elbow;
    float base = fmodf(rad2deg(atan2f(y, x)) + 360.0f, 360.0f);

    float joint[ARM_API_MAX_SERVOS] = { base, rad2deg(shoulder), rad2deg(elbow),
                                        rad2deg(wrist), 0.0f };
    for (int i = 0; i < 4; i++) {
        servo_out[i] = servo_of_joint(i, joint[i]);
        if (joint_out) {
            joint_out[i] = joint[i];
        }
    }
    /* base 需要映射到 0..360 之外的等效值：舵机行程只有 0..180，
       方位角超出 [0,180] 的目标物理上不可达（与上位机实测一致） */
    for (int i = 0; i < 4; i++) {
        if (servo_out[i] < (float)servo_min(i) || servo_out[i] > (float)servo_max(i)) {
            ESP_LOGW(TAG, "IK: 关节 %d 舵机角 %.1f 超出 [%d, %d]",
                     i, servo_out[i], servo_min(i), servo_max(i));
            return ESP_ERR_INVALID_STATE;
        }
    }
    return ESP_OK;
}

