{"content": """"补齐缺失的 ESP-IDF 子模块：解析 .gitmodules 全部路径 → 查 API 取 pin 的 commit → 下载。"""

import io
import json
import os
import re
import shutil
import sys
import tarfile
import time
import urllib.request

IDF = r"C:\esp32-tools\esp-idf"


def parse_gitmodules():
    out = {}
    txt = open(os.path.join(IDF, ".gitmodules"), encoding="utf-8").read()
    for block in txt.split("[submodule")[1:]:
        p = re.search(r'path\s*=\s*(\S+)', block)
        u = re.search(r'url\s*=\s*(\S+)', block)
        if p and u:
            out[p.group(1)] = u.group(1)
    return out


def to_repo(url):
    u = re.sub(r"^https?://github\.com/", "", url.strip())
    u = re.sub(r"^(\.\./)+", "", u)
    return re.sub(r"\.git$", "", u)


def sha_of(path):
    url = "https://api.github.com/repos/espressif/esp-idf/contents/%s?ref=v5.4" % path
    for _ in range(3):
        try:
            with urllib.request.urlopen(url, timeout=30) as r:
                j = json.loads(r.read().decode())
            if isinstance(j, dict) and j.get("type") == "submodule":
                return j.get("sha")
        except Exception as e:
            print("   API 失败(%s)，重试" % e)
            time.sleep(2)
    return None


def fetch(repo, sha, dest):
    url = "https://codeload.github.com/%s/tar.gz/%s" % (repo, sha)
    data = None
    for attempt in range(3):
        try:
            with urllib.request.urlopen(url, timeout=240) as r:
                data = r.read()
            break
        except Exception as e:
            print("   重试 %d: %s" % (attempt + 1, e))
            time.sleep(2)
    if not data or len(data) < 800:
        return False
    with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as tf:
        if os.path.exists(dest):
            shutil.rmtree(dest, ignore_errors=True)
        os.makedirs(dest, exist_ok=True)
        for m in [x for x in tf.getmembers() if not (x.issym() or x.islnk())]:
            m.name = "/".join(m.name.split("/")[1:])
            if not m.name:
                continue
            if m.isdir():
                os.makedirs(os.path.join(dest, m.name), exist_ok=True)
            elif m.isfile():
                p = os.path.join(dest, m.name)
                os.makedirs(os.path.dirname(p), exist_ok=True)
                with open(p, "wb") as f:
                    f.write(tf.extractfile(m).read())
    return True


def main():
    only = sys.argv[1:] if len(sys.argv) > 1 else None
    gm = parse_gitmodules()
    print("子模块条目 %d" % len(gm))
    for path, url in gm.items():
        if only and path not in only:
            continue
        dest = os.path.join(IDF, path)
        if os.path.isdir(dest) and os.listdir(dest):
            print("已存在 %s" % path)
            continue
        sha = sha_of(path)
        if not sha:
            print("无 SHA，跳过 %s" % path)
            continue
        repo = to_repo(url)
        print("-- %s <- %s@%s" % (path, repo, sha[:8]))
        print("   %s" % ("ok" if fetch(repo, sha, dest) else "失败"))


if __name__ == "__main__":
    main()
