            body["speed"] = speed
            if "gripper" in cmd:
                body["gripper"] = cmd["gripper"]
            resp = self.client._req("/api/move_xyz", body)
        else:
            speed = self._speed_for_joints(cmd, dur, cur)
            body = {k: v for k, v in cmd.items() if not k.startswith("_")}
            body["speed"] = speed
            resp = self.client.move(body, speed=speed)
        settled, took = self.wait_settled()
        out = {"sent": {k: (round(v, 1) if isinstance(v, float) else v)
