=== arm_api.h ===
/*
 * arm_api —— 面向 AI/上位机的机械臂控制接口
 *
 * 设计要点（与上位机数字孪生逐项对应）：
 *   1. 唯一运动任务：所有关节指令先进队列，由 50 Hz 运动任务统一插值输出，
 *      彻底消除"每个关节一条任务 + 无仲裁"导致的指令打架问题；
 *   2. 重定向语义：/api/move 立即改写目标（适合视觉伺服的连续小步修正），
 *      /api/trajectory 提交整条轨迹（适合预规划动作），二者互不阻塞；
 *   3. 关节角 -> 舵机角 的标定表：joint = s * servo + o，存 NVS，可在线标定；
 *   4. 笛卡尔接口：/api/pose 正解、/api/move_xyz 逆解（超出工作空间或行程时
 *      明确报错，而不是静默截断）；
 *   5. 安全：急停 /api/estop、停止 /api/stop（保持位置）、指令保活超时、
 *      学习模式（手动/录制/回放）期间拒绝 AI 指令。
 */

#pragma once

#include <stdbool.h>
#include <stdint.h>

#include "esp_err.h"
#include "freertos/FreeRTOS.h"
#include "freertos/queue.h"
#include "esp_http_server.h"
#include "robotic_arm.h"

#ifdef __cplusplus
extern "C" {
#endif

#define ARM_API_MAX_SERVOS         ROBOTIC_ARM_MAX_SERVOS
#define ARM_API_MAX_WAYPOINTS      8        /* 单次 /api/trajectory 的路径点数 */
#define ARM_API_BODY_MAX           1024     /* JSON 请求体上限（原 /api/control 只有 99 字节） */
#define ARM_API_TICK_HZ            50
#define ARM_API_DEFAULT_SPEED      60.0f    /* deg/s */
#define ARM_API_MIN_SPEED          5.0f
#define ARM_API_MAX_SPEED          180.0f
#define ARM_API_WATCHDOG_MS        3000     /* 超过该时间无指令则按当前目标保持 */
#define ARM_API_MOVE_TIMEOUT_MS    15000    /* 单条指令最长执行时间，超时停机 */

typedef struct {
    robotic_arm_handle_t *arm;      /*!< 机械臂句柄 */
    float speed_default;            /*!< 默认速度 deg/s */
} arm_api_config_t;

/* 关节角与舵机角的标定关系：joint = sign * servo + offset */
typedef struct {
    int8_t  sign[ARM_API_MAX_SERVOS];
    float   offset[ARM_API_MAX_SERVOS];
} arm_api_calib_t;

/* 统一状态快照（供 HTTP 与内部逻辑使用） */
typedef struct {
    float   angle[ARM_API_MAX_SERVOS];    /*!< 当前舵机角（插值后的实际指令值） */
    float   target[ARM_API_MAX_SERVOS];   /*!< 目标舵机角 */
    bool    moving;                       /*!< 是否仍在运动 */
    bool    estop;                        /*!< 急停锁存 */
