        for (int i = 0; i < ARM_API_MAX_SERVOS; i++) {
            required_out[i] = servo[i];
        }
    }
    if (allowed_out) {
        for (int i = 0; i < ARM_API_MAX_SERVOS; i++) {
            allowed_out[i * 2] = (float)servo_min(i);
            allowed_out[i * 2 + 1] = (float)servo_max(i);
