    arm_api_get_state(&st);
    robotic_arm_angles_t target = {
        (uint8_t)lroundf(clampf(servo[0], servo_min(0), servo_max(0))),
        (uint8_t)lroundf(clampf(servo[1], servo_min(1), servo_max(1))),
        (uint8_t)lroundf(clampf(servo[2], servo_min(2), servo_max(2))),
