{"content": "/*
 * serial_api —— 电脑通过 USB 串口直接控制机械臂
 *
 * 设计目标：让上位机（或任何串口终端）用与 HTTP 完全相同的能力控制机械臂，
 * 不需要 Wi-Fi、不需要电位器控制臂。
 *
 * 协议：一行一条 JSON 指令，一行一条 JSON 回复，UTF-8，以 '\n' 结尾。
 *   {"cmd":"move","base":90,...}          -> {"ok":true,"seq":3}
 *   {"cmd":"move_xyz","x":150,"y":60,"z":170,"pitch":90,"gripper":45}
 *   {"cmd":"state"}                       -> 与 HTTP /api/state 同格式
 *   {"cmd":"limits"}                      -> 与 HTTP /api/limits 同格式
 *   {"cmd":"stop"} / {"cmd":"estop"} / {"cmd":"home"}
 *   {"cmd":"calib_get"} / {"cmd":"calib_set","sign":[...],"offset":[...]}
 *   {"cmd":"ping"}                        -> {"ok":true,"pong":true}
 *
 * 任何未知指令返回 {"ok":false,"err":"unknown_cmd","cmd":"..."}，
 * 参数错误返回具体原因 —— 上位机与 AI 据此自我修正。
 *
 * 使用 ESP-IDF 的控制台 UART（默认 UART0，即板载 USB 串口，115200）。
 * 注意：UART0 同时承载 ESP_LOG 输出，因此本组件在串口模式下会把日志
 * 输出降级/改道，避免日志与协议混在一行里（见 serial_api_init 的 log_redirect）。
 */

#pragma once

#include <stdbool.h>
#include <stdint.h>

#include "esp_err.h"
#include "robotic_arm.h"

#ifdef __cplusplus
extern "C" {
#endif

#define SERIAL_API_LINE_MAX   1024      /* 单行 JSON 上限，与 ARM_API_BODY_MAX 对齐 */
#define SERIAL_API_DEFAULT_BAUD 115200

typedef struct {
    robotic_arm_handle_t *arm;      /*!< 机械臂句柄 */
    int  uart_num;                  /*!< UART 端口，默认 0 */
    int  tx_pin;                    /*!< <0 表示使用默认引脚 */
    int  rx_pin;
    int  baud_rate;                 /*!< <=0 表示使用默认 115200 */
    bool echo;                      /*!< 回显收到的指令（调试用） */
    bool log_to_uart;               /*!< 是否允许 ESP_LOG 继续占用该串口（默认 false） */
} serial_api_config_t;

/**
 * @brief 初始化串口接口并创建接收任务
 */
esp_err_t serial_api_init(const serial_api_config_t *config);

/**
 * @brief 主动发送一行 JSON（供内部与调试使用）
 */
esp_err_t serial_api_send(const char *line);

#ifdef __cplusplus
}
#endif
