{"content": "/*
 * serial_api 实现：一行一条 JSON，走 UART0（板载 USB 串口）。
 *
 * 与 HTTP 版本的差异只有一个：传输介质。指令语义、错误码、越界报告
 * 全部复用 arm_api 的公开函数，因此两条通道能力完全一致。
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "serial_api.h"

#include "cJSON.h"
#include "driver/uart.h"
#include "esp_log.h"
#include "esp_timer.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "arm_api.h"

static const char *TAG = "SERIAL_API";

static serial_api_config_t s_cfg;
static bool s_inited = false;

/* ------------------------------------------------------------------ */
/* 输出                                                                */
/* ------------------------------------------------------------------ */

esp_err_t serial_api_send(const char *line)
{
    if (!line) {
        return ESP_ERR_INVALID_ARG;
    }
    size_t n = strlen(line);
    uart_write_bytes((uart_port_t)s_cfg.uart_num, line, n);
    uart_write_bytes((uart_port_t)s_cfg.uart_num, "\n", 1);
    return ESP_OK;
}

static void send_obj(cJSON *obj)
{
    char *out = cJSON_PrintUnformatted(obj);
    if (out) {
        serial_api_send(out);
        free(out);
    }
    cJSON_Delete(obj);
}

static void send_ok(bool ok)
{
    cJSON *r = cJSON_CreateObject();
    cJSON_AddBoolToObject(r, "ok", ok);
    send_obj(r);
}

static void send_err(const char *reason)
{
    cJSON *r = cJSON_CreateObject();
    cJSON_AddBoolToObject(r, "ok", false);
    cJSON_AddStringToObject(r, "err", reason);
    send_obj(r);
}

/* 越界时返回具体关节、给定值与允许范围，便于上位机/AI 自我修正 */
static void send_range_err(const char *joint, double value, int lo, int hi)
{
    cJSON *r = cJSON_CreateObject();
    cJSON_AddBoolToObject(r, "ok", false);
    cJSON_AddStringToObject(r, "err", "range");
    cJSON_AddStringToObject(r, "joint", joint);
    cJSON_AddNumberToObject(r, "value", value);
    cJSON_AddNumberToObject(r, "min", lo);
    cJSON_AddNumberToObject(r, "max", hi);
    send_obj(r);
}

static double num_or(cJSON *o, const char *key, double dflt)
{
    cJSON *it = cJSON_GetObjectItem(o, key);
    return cJSON_IsNumber(it) ? it->valuedouble : dflt;
}

static bool has_num(cJSON *o, const char *key)
{
    return cJSON_IsNumber(cJSON_GetObjectItem(o, key));
}

/* ------------------------------------------------------------------ */
/* 各指令处理                                                          */
/* ------------------------------------------------------------------ */

static void handle_state(void)
{
    char buf[512];
    if (arm_api_state_json(buf, sizeof(buf)) != ESP_OK) {
        send_err("not_initialized");
        return;
    }
    serial_api_send(buf);
}

static void handle_limits(void)
{
    char buf[640];
    if (arm_api_limits_json(buf, sizeof(buf)) != ESP_OK) {
        send_err("not_initialized");
        return;
    }
    serial_api_send(buf);
}

static void handle_pose(void)
{
    /* /api/pose 的核心：由当前舵机角做正解 */
    arm_api_state_t st;
    if (arm_api_get_state(&st) != ESP_OK) {
        send_err("not_initialized");
        return;
    }
    cJSON *r = cJSON_CreateObject();
    cJSON_AddBoolToObject(r, "ok", true);
    cJSON *a = cJSON_AddObjectToObject(r, "angles");
    cJSON_AddNumberToObject(a, "base", st.angle[0]);
    cJSON_AddNumberToObject(a, "shoulder", st.angle[1]);
    cJSON_AddNumberToObject(a, "elbow", st.angle[2]);
    cJSON_AddNumberToObject(a, "wrist", st.angle[3]);
    cJSON_AddNumberToObject(a, "gripper", st.angle[4]);
    send_obj(r);
}

static void handle_move(cJSON *root)
{
    static const char *names[ARM_API_MAX_SERVOS] = {
        "base", "shoulder", "elbow", "wrist", "gripper"
    };
    arm_api_state_t st;
    if (arm_api_get_state(&st) != ESP_OK) {
        send_err("not_initialized");
        return;
    }
    uint8_t cur[ARM_API_MAX_SERVOS];
    for (int i = 0; i < ARM_API_MAX_SERVOS; i++) {
        cur[i] = (uint8_t)st.angle[i];
    }

    bool any = false;
    for (int i = 0; i < ARM_API_MAX_SERVOS; i++) {
        if (!has_num(root, names[i])) {
            continue;
        }
        double v = num_or(root, names[i], 0);
        if (!(v >= 0.0 && v <= 270.0)) {      /* 明显非法的先挡掉 */
            send_range_err(names[i], v, 0, 270);
            return;
        }
        any = true;
    }
    if (!any) {
        send_err("no_joint_given");
        return;
    }
    /* 用 limits 里的真实行程校验，避免与固件配置脱节 */
    char lbuf[640];
    if (arm_api_limits_json(lbuf, sizeof(lbuf)) == ESP_OK) {
        cJSON *lim = cJSON_Parse(lbuf);
        cJSON *joints = lim ? cJSON_GetObjectItem(lim, "joints") : NULL;
        for (int i = 0; i < ARM_API_MAX_SERVOS; i++) {
            if (!has_num(root, names[i]) || !joints) {
                continue;
            }
            cJSON *j = cJSON_GetObjectItem(joints, names[i]);
            int lo = (int)num_or(j, "min", 0);
            int hi = (int)num_or(j, "max", 180);
            double v = num_or(root, names[i], 0);
            if (v < lo || v > hi) {
                cJSON_Delete(lim);
                send_range_err(names[i], v, lo, hi);
                return;
            }
        }
        cJSON_Delete(lim);
    }

    for (int i = 0; i < ARM_API_MAX_SERVOS; i++) {
        if (has_num(root, names[i])) {
            cur[i] = (uint8_t)(num_or(root, names[i], 0) + 0.5);
        }
