{"content": """"串口客户端：电脑通过 USB 串口直接控制机械臂（替代 HTTP/Wi-Fi）。

与 `servo_loop.ArmClient`（HTTP 版）保持完全相同的接口，
因此 agent 主循环、视觉伺服、安全校验层都不用改，只换传输通道。

协议：一行一条 JSON 指令，一行一条 JSON 回复（UTF-8，'\n' 结尾）。
固件侧实现在 `components/serial_api/`。

用法：
    from serial_client import SerialArmClient
    arm = SerialArmClient("COM5")           # 或 "/dev/ttyUSB0"
    arm.state()                             # 与 HTTP 版同名字段
    arm.move({"base": 90, "shoulder": 60})
    arm.move_xyz(150, 60, 170, pitch=90, gripper=45)
    arm.home(); arm.stop(); arm.estop()

找不到端口时用 `list_ports()` 看可用串口。
"""

import json
import time

try:
    import serial
    from serial.tools import list_ports as _list_ports
except ImportError as e:      # pragma: no cover
    raise ImportError("需要 pyserial：pip install pyserial") from e


class SerialError(RuntimeError):
    pass


def list_ports():
    """返回 [(设备名, 描述)]，用于挑选串口。"""
    return [(p.device, p.description) for p in _list_ports.comports()]


def find_esp32_port(prefer=None):
    """按描述猜一个像是 ESP32 的串口；找不到返回 None。

    ESP32 的 USB 转串口芯片常见描述：CP210x、CH340、CH9102、USB-SERIAL。
    """
    if prefer:
        return prefer
    cands = list_ports()
    keys = ("cp210", "ch340", "ch910", "usb-serial", "usb serial", "silicon labs")
    for dev, desc in cands:
        d = (desc or "").lower()
        if any(k in d for k in keys):
            return dev
    return cands[0][0] if cands else None


class SerialArmClient:
    """与 ArmClient（HTTP）同接口的串口实现。"""

    def __init__(self, port=None, baud=115200, timeout=3.0, verbose=False,
                 reset_on_open=True):
        self.port = find_esp32_port(port)
        if not self.port:
            raise SerialError("没有可用串口。已发现：%s" % (list_ports() or "无"))
        self.baud = int(baud)
        self.timeout = float(timeout)
        self.verbose = verbose
        self.calls = 0
        # dsrdtr/rtscts 必须关闭：否则打开串口时会复位 ESP32 或阻塞
        self.ser = serial.Serial(port=self.port, baudrate=self.baud,
                                 timeout=self.timeout, write_timeout=self.timeout,
                                 dsrdtr=False, rtscts=False)
        self.ser.dtr = False
        self.ser.rts = False
        if reset_on_open:
            # 很多 ESP32 板子靠 DTR/RTS 复位；不复位的话残留数据会混进首条回复
            time.sleep(0.3)
            self.ser.reset_input_buffer()
        self._last_seq = None

    # ---------- 底层 ----------
    def _send(self, obj):
        line = json.dumps(obj, ensure_ascii=False) + "\n"
        try:
            self.ser.write(line.encode("utf-8"))
            self.ser.flush()
        except Exception as e:
            raise SerialError("写串口失败(%s): %s" % (self.port, e))

    def _read_reply(self, max_lines=40):
        """读回复。容忍固件日志行：只认第一行合法 JSON。"""
        for _ in range(max_lines):
            raw = self.ser.readline()
            if not raw:
                raise SerialError("串口超时 %.1fs 未收到回复（检查波特率/端口/固件）"
                                  % self.timeout)
            line = raw.decode("utf-8", "replace").strip()
            if not line:
                continue
            if line[0] not in "{[":
                if self.verbose:
                    print("[fw] %s" % line[:120])
                continue                     # 跳过 esp_log 输出
            try:
                return json.loads(line)
            except json.JSONDecodeError:
                if self.verbose:
                    print("[非 JSON] %s" % line[:120])
                continue
        raise SerialError("连续 %d 行都不是合法 JSON，可能波特率不对" % max_lines)

    def request(self, obj, retries=2):
        """发一条指令并等回复。"""
        last = None
        for attempt in range(retries + 1):
            try:
                self._send(obj)
                resp = self._read_reply()
                self.calls += 1
                if isinstance(resp, dict) and "seq" in resp:
                    self._last_seq = resp["seq"]
                return resp
            except SerialError as e:
                last = e
                if attempt < retries:
                    time.sleep(0.15 * (attempt + 1))
        raise last

    # ---------- 与 ArmClient 同名的方法 ----------
    def state(self):
        """返回与 HTTP /api/state 相同的字段结构，供上层无差别使用。"""
        r = self.request({"cmd": "state"})
        if "angles" in r:
            return r
        raise SerialError("state 返回异常: %s" % r)

    def limits(self):
        return self.request({"cmd": "limits"})

    def pose(self):
        return self.request({"cmd": "pose"})

    def move(self, angles, speed=60.0):
        body = {"cmd": "move"}
        for k in ("base", "shoulder", "elbow", "wrist", "gripper"):
            if k in angles and angles[k] is not None:
                body[k] = float(angles[k])
        if speed:
            body["speed"] = float(speed)
        return self.request(body)

    def move_xyz(self, x, y, z, pitch=90.0, gripper=None, speed=60.0, elbow_up=False):
        body = {"cmd": "move_xyz", "x": float(x), "y": float(y), "z": float(z),
                "pitch": float(pitch), "speed": float(speed)}
        if elbow_up:
            body["elbow_up"] = True
        if gripper is not None:
            body["gripper"] = float(gripper)
        return self.request(body)

    def trajectory(self, points, speed=60.0):
        return self.request({"cmd": "trajectory", "points": points, "speed": float(speed)})

    def home(self):
        return self.request({"cmd": "home"})

    def stop(self):
        return self.request({"cmd": "stop"})

    def estop(self, clear=False):
        return self.request({"cmd": "estop", "clear": bool(clear)})

    def calib_get(self):
        return self.request({"cmd": "calib_get"})

