{"content": """"串口协议孪生：在 PC 上复刻固件 serial_api 的行为，用于端到端验证上位机客户端。

它复用已有的 ArmTwin（运动学、限位、唯一运动任务），只把"传输层"换成
TCP socket，从而可以用 pyserial 的 socket:// 通道把真实的 SerialArmClient
原封不动地接上去测试 —— 客户端代码路径与接真机时完全一致。

同时它逐行复刻了固件 serial_api.c 的协议细节：
  * 一行一条 JSON，'\n' 结束；'\r' 忽略；
  * 未知指令回 unknown_cmd 并带 hint；
  * 越界回 range + joint/value/min/max；
  * 逆解失败回 unreachable + required_servo + allowed；
  * 超长行回 line_too_long（并丢弃整行）。
"""

import json
import socketserver
import threading

from firmware_twin import ArmTwin, JOINTS, SERVO_SPECS
from arm_model import ARM_JOINTS, MODEL_CAL, ik_model, joint_to_servo

LINE_MAX = 1024


class SerialTwin:
    """把 ArmTwin 包一层串口协议语义。"""

    def __init__(self):
        self.twin = ArmTwin()
        self.lines = []          # 收到的原始行，便于测试断言

    # ---------- 各指令 ----------
    def _limits(self):
        out = {"ok": True, "joints": {}, "speed": {"min": 5.0, "max": 180.0,
                                                  "default": self.twin.speed}}
        for j in JOINTS:
            out["joints"][j] = {"min": SERVO_SPECS[j]["min_angle"],
                                "max": SERVO_SPECS[j]["max_angle"],
                                "home": SERVO_SPECS[j]["home"]}
        out["workspace"] = {"base_height": 85.0, "reach_max": 255.0}
        return out

    def handle(self, line):
        self.lines.append(line)
        try:
            root = json.loads(line)
        except Exception:
            return {"ok": False, "err": "invalid_json"}
        if not isinstance(root, dict) or not isinstance(root.get("cmd"), str):
            return {"ok": False, "err": "cmd_required"}
        cmd = root["cmd"]

        if cmd == "ping":
            return {"ok": True, "pong": True, "fw": "serial_api"}
        if cmd == "state":
            return self.twin.state_v2()
        if cmd == "limits":
            return self._limits()
        if cmd == "pose":
            with self.twin.lock:
                cur = {j: self.twin.pwm[j] for j in JOINTS}
            return {"ok": True, "angles": cur}
        if cmd == "move":
            return self._move(root)
        if cmd == "move_xyz":
            return self._move_xyz(root)
        if cmd == "trajectory":
            return self._trajectory(root)
        if cmd == "home":
            ok, info = self.twin.v2_home()
            return {"ok": bool(ok), **info}
        if cmd == "stop":
            ok, info = self.twin.v2_stop()
            st = self.twin.state_v2()
            return {"ok": True, "seq": info.get("seq"), "estop": st["estop"]}
        if cmd == "estop":
            if root.get("clear"):
                with self.twin.lock:
                    self.twin.estop = False
                    for j in JOINTS:
                        self.twin.pwm[j] = float(SERVO_SPECS[j]["home"])
                        self.twin.target[j] = self.twin.pwm[j]
                return {"ok": True, "estop": False}
            ok, info = self.twin.v2_stop(release=True)
            return {"ok": True, "estop": True}
        if cmd == "calib_get":
            return {"ok": True, "sign": MODEL_CAL["s"], "offset": MODEL_CAL["o"]}
        if cmd == "calib_set":
            return {"ok": True, "saved": True}
        return {"ok": False, "err": "unknown_cmd", "cmd": cmd,
                "hint": "支持: ping state limits pose move move_xyz trajectory "
                        "home stop estop calib_get calib_set"}

    def _move(self, root):
        cur = {}
        with self.twin.lock:
            for j in JOINTS:
                cur[j] = float(self.twin.pwm[j])
        any_j = False
        lim = self._limits()["joints"]
        for j in JOINTS:
            if not isinstance(root.get(j), (int, float)):
                continue
            v = float(root[j])
            if v < lim[j]["min"] or v > lim[j]["max"]:
                return {"ok": False, "err": "range", "joint": j, "value": v,
                        "min": lim[j]["min"], "max": lim[j]["max"]}
            cur[j] = v
            any_j = True
        if not any_j:
            return {"ok": False, "err": "no_joint_given"}
        ok, info = self.twin.v2_move(cur, root.get("speed"))
        if not ok:
            return {"ok": False, "err": "busy_or_estop"}
        return {"ok": True, "seq": info.get("seq"),
                "target": {j: round(cur[j], 1) for j in JOINTS}}

    def _move_xyz(self, root):
        for k in ("x", "y", "z"):
            if not isinstance(root.get(k), (int, float)):
                return {"ok": False, "err": "x_y_z_required"}
        x, y, z = float(root["x"]), float(root["y"]), float(root["z"])
        pitch = float(root.get("pitch", 90.0))
        try:
            ang = ik_model((x, y, z), pitch)
            srv = joint_to_servo(ang, MODEL_CAL)
        except Exception as e:
            return {"ok": False, "err": "unreachable", "detail": str(e),
                    "required_servo": {j: None for j in JOINTS},
                    "allowed": {j: {"min": SERVO_SPECS[j]["min_angle"],
                                    "max": SERVO_SPECS[j]["max_angle"]}
                                for j in JOINTS}}
        bad = None
        for j in ARM_JOINTS:
            lo, hi = SERVO_SPECS[j]["min_angle"], SERVO_SPECS[j]["max_angle"]
            if not (lo <= srv[j] <= hi):
                bad = (j, srv[j], lo, hi)
                break
        if bad:
            return {"ok": False, "err": "joint_limit",
                    "joint": bad[0], "value": round(bad[1], 1),
                    "min": bad[2], "max": bad[3],
                    "required_servo": {j: round(srv[j], 1) for j in ARM_JOINTS} …[截断,原长9275]

