def make_rig_staggered(center=(0.0, 0.0, 150.0), size=(640, 480), fov_deg=62.0):
    """错落高度布置：三台相机方位约 120 度分开，高度与距离各不相同。

    实测同高对称布置下末端标记更容易被自身连杆挡住（见报告"相机布置"一节）。
    """
    spec = ((35.0, 380.0, 820.0), (155.0, 640.0, 780.0), (275.0, 880.0, 740.0))
    cams = []
    for i, (az, h, rad) in enumerate(spec):
        a = math.radians(az)
        eye = (center[0] + rad * math.cos(a), center[1] + rad * math.sin(a), h)
        cams.append(Camera(eye, center, size=size, fov_deg=fov_deg, name="cam%d" % i))
    return cams


def make_rig_one_top(center=(0.0, 0.0, 120.0), size=(640, 480), fov_deg=62.0):
    """三相机方案 B：一台近顶视 + 两台侧视（方位约 150 度分开）。

    近底座的目标会被机械臂自身完全挡住，纯侧视布置看不到（见报告实测），
    俯视相机是解决该问题的关键。
    """
    cams = [Camera((120.0, -40.0, 900.0), center, size=size, fov_deg=fov_deg, name="top")]
    for i, (az, h, rad) in enumerate(((-20.0, 430.0, 800.0), (150.0, 700.0, 760.0))):
        a = math.radians(az)
        eye = (rad * math.cos(a), rad * math.sin(a), h)
        cams.append(Camera(eye, center, size=size, fov_deg=fov_deg, name="cam%d" % i))
    return cams


def make_rig(center=(0.0, 0.0, 140.0), radius=760.0, height=560.0,
             azimuths=(35.0, 155.0, 275.0), size=(640, 480), fov_deg=62.0):
    cams = []
    for i, az in enumerate(azimuths):
        a = math.radians(az)
        eye = (center[0] + radius * math.cos(a), center[1] + radius * math.sin(a), height)
        cams.append(Camera(eye, center, size=size, fov_deg=fov_deg, name="cam%d" % i))
    return cams


