import re, collections, io, math
p = r"3D/开源机械臂(原版3d机构件)/Compact Robot Arm STEP FILES.step"
txt = open(p, 'r', encoding='utf-8', errors='ignore').read()
ents = {}
for m in re.finditer(r"#(\d+)\s*=\s*([A-Z_0-9]+)\s*\((.*?)\)\s*;", txt, re.S):
    ents[int(m.group(1))] = (m.group(2), m.group(3))
cnt = collections.Counter(t for t,_ in ents.values())
out = io.StringIO()
for k in sorted(cnt):
    if any(s in k for s in ("TRANSFORM","RELATIONSHIP","MAPPED","BREP","SHAPE_REP","ITEM_DEFINED")):
        out.write("%s: %d\n" % (k, cnt[k]))
out.write("\n")

def refs(a):
    return [int(x) for x in re.findall(r"#(\d+)", a)]

def pt(x):
    m = re.match(r"\s*\(?\s*([-0-9.E+]+)\s*,\s*([-0-9.E+]+)\s*,\s*([-0-9.E+]+)", x.strip())
    return tuple(float(v) for v in m.groups()) if m else None

cache = {}
def verts(ent_id, depth=0):
    if ent_id in cache: return cache[ent_id]
    if depth > 40: return []
    t, a = ents.get(ent_id, ("?", ""))
    res = []
    if t == "CARTESIAN_POINT":
        v = pt(a.split(",",1)[1] if a.count(",")>=3 else a)
        res = [v] if v else []
    elif t in ("VERTEX_POINT","EDGE_CURVE","ORIENTED_EDGE","EDGE_LOOP","FACE_OUTER_BOUND",
               "FACE_BOUND","ADVANCED_FACE","CLOSED_SHELL","OPEN_SHELL","MANIFOLD_SOLID_BREP",
               "ORIENTED_CLOSED_SHELL","BREP_WITH_VOIDS","SHELL_BASED_SURFACE_MODEL",
               "ADVANCED_BREP_SHAPE_REPRESENTATION"):
        for r in refs(a):
            res.extend(verts(r, depth+1))
    cache[ent_id] = res
    return res

solids=[]
for i,(t,a) in ents.items():
    if t=="MANIFOLD_SOLID_BREP":
        name=a.split(",")[0].strip().strip("'")
        vs = verts(i)
        if vs:
            xs=[v[0] for v in vs]; ys=[v[1] for v in vs]; zs=[v[2] for v in vs]
            bbox=(max(xs)-min(xs), max(ys)-min(ys), max(zs)-min(zs))
            cen=((max(xs)+min(xs))/2,(max(ys)+min(ys))/2,(max(zs)+min(zs))/2)
        else:
            bbox=(0,0,0); cen=(0,0,0)
            vs=[]
        # face count
        shell=refs(a)[0] if refs(a) else None
        nf = 0
        if shell is not None:
            nf = len(refs(ents[shell][1]))
        solids.append((i,name,bbox,cen,nf,len(vs),len(ents[shell][1]) if shell else 0))

out.write("id     name      dx       dy       dz     center(x,y,z)          faces  verts\n")
for i,name,bb,cen,nf,nv,ra in sorted(solids, key=lambda s: s[1]):
    out.write("#%-6d %-8s %7.1f %7.1f %7.1f   (%7.1f,%7.1f,%7.1f)  %5d %5d\n" % (i,name,bb[0],bb[1],bb[2],cen[0],cen[1],cen[2],nf,nv))
open(r"C:\esp32-tools\step_bbox.txt","w",encoding="utf-8").write(out.getvalue())
print("done", len(solids))
PYEOF
