# -*- coding: utf-8 -*-
"""按零件列出所有孔，并找常见的安装孔距（舵机耳 49.5mm 等）。"""
import os, warnings; warnings.filterwarnings("ignore")
import numpy as np
from hole_pairs import holes, names, MSH

for nm in ["B1","B2","M1","M2","F1","F2","F2C","G1+G2","MB1","MB2","MB3","MB4","MB1R"]:
    if nm not in MSH: continue
    hs = holes(MSH[nm], dmin=1.2)
    if not hs: continue
    print("\n=== %s ===" % nm)
    for h in sorted(hs, key=lambda x:(x["axis"], -x["d"])):
        print("   Ø%5.2f %s  depth %5.2f   at (%8.2f,%8.2f,%8.2f)" % (
            h["d"], "XYZ"[h["axis"]], abs(h["a1"]-h["a0"]), *h["perp"][[0,1]],
            (h["a0"]+h["a1"])/2))
    print("   -- 孔距 --")
    for i in range(len(hs)):
        for j in range(i+1,len(hs)):
            a,b=hs[i],hs[j]
            if abs(a["d"]-b["d"])>0.6: continue
            if a["axis"]!=b["axis"]: continue
            d=np.linalg.norm(a["perp"]-b["perp"])
            if 6<d<60:
                flag=""
                for tgt in (49.5, 50.0, 40.0, 30.5, 20.0, 10.0, 22.0, 15.0):
                    if abs(d-tgt)<0.8: flag="  <== %.1f"%tgt
                if flag: print("      Ø%.1f x2 间距 %6.2f mm%s"%(a["d"],d,flag))
PYEOF
